import { useCallback, useState } from 'react';
import { JxCalendar, JxChip } from '@jinx-ui/react';

interface ReportDatePickerProps {
  value?: Date | null;
  defaultValue?: Date | null;
  onChange?: (value: Date | null) => void;
  locale?: string;
}

const startOfDay = (date: Date): Date =>
  new Date(date.getFullYear(), date.getMonth(), date.getDate());

const shiftDays = (days: number): Date => {
  const base = startOfDay(new Date());
  base.setDate(base.getDate() + days);
  return base;
};

const presets: Array<{ id: string; label: string; offset: number }> = [
  { id: 'today', label: 'Сегодня', offset: 0 },
  { id: 'yesterday', label: 'Вчера', offset: -1 },
  { id: 'week-ago', label: 'Неделя назад', offset: -7 },
];

const isSameDay = (a: Date | null, b: Date | null): boolean =>
  a != null && b != null && startOfDay(a).getTime() === startOfDay(b).getTime();

export default function ReportDatePicker({
  value,
  defaultValue = null,
  onChange,
  locale = 'ru-RU',
}: ReportDatePickerProps) {
  const [internal, setInternal] = useState<Date | null>(defaultValue);
  const selected = value !== undefined ? value : internal;

  const select = useCallback(
    (next: Date | null) => {
      if (value === undefined) setInternal(next);
      onChange?.(next);
    },
    [onChange, value],
  );

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
      <div
        role="group"
        aria-label="Быстрый выбор даты отчёта"
        style={{ display: 'flex', flexWrap: 'wrap', gap: 8 }}
      >
        {presets.map((preset) => {
          const presetDate = shiftDays(preset.offset);
          const active = isSameDay(selected, presetDate);
          return (
            <JxChip
              key={preset.id}
              role="button"
              tabIndex={0}
              aria-pressed={active}
              active={active}
              onClick={() => select(shiftDays(preset.offset))}
              onKeyDown={(event) => {
                if (event.key === 'Enter' || event.key === ' ') {
                  event.preventDefault();
                  select(shiftDays(preset.offset));
                }
              }}
            >
              {preset.label}
            </JxChip>
          );
        })}
      </div>

      <JxCalendar locale={locale} value={selected} onValueChange={select} />

      <p
        aria-live="polite"
        style={{ margin: 0, color: 'var(--jx-text-2)', fontFamily: 'var(--jx-font-sans)' }}
      >
        {selected
          ? `Дата отчёта: ${selected.toLocaleDateString(locale, {
              day: 'numeric',
              month: 'long',
              year: 'numeric',
            })}`
          : 'Дата не выбрана — нажмите вариант выше или день в календаре.'}
      </p>
    </div>
  );
}

